from typing import List
from itertools import groupby


def getUnallottedUsers(bids: List[List[int]], totalShares: int) -> List[int]:
    # 价格降序，同价按 timestamp 升序
    order = sorted(bids, key=lambda b: (-b[2], b[3]))
    got = set()
    left = totalShares
    for _, grp in groupby(order, key=lambda b: b[2]):
        if left == 0:
            break
        grp = list(grp)
        need = sum(b[1] for b in grp)
        if need <= left:
            got.update(b[0] for b in grp)
            left -= need
        else:
            # 不够全部满足：轮转第一圈就把股份发给前 min(left, k) 个人，之后股份用完
            got.update(b[0] for b in grp[:left])
            left = 0
    return sorted({b[0] for b in bids} - got)


if __name__ == "__main__":
    print(getUnallottedUsers([[1, 5, 7, 0], [2, 7, 8, 1], [3, 7, 7, 2], [4, 10, 6, 3]], 18))
    print(getUnallottedUsers([[1, 2, 5, 0], [2, 2, 5, 1], [3, 1, 4, 2]], 2))
